  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('mypl/beloved son',cases['17-5']['analysis'])
  self.assertIn('ipl well kjv_please_satisfy:psv:pr',cases['17-5']['analysis'])
  self.assertIn('five+twelve and ten kjv_fold seven',cases['18-22']['analysis'])
  self.assertIn('i to thou all that debt forgive:pa',cases['18-32']['analysis'])
  self.assertIn('mypl/heavenly father',cases['18-35']['analysis'])
